function selectOne(e,group){var locations=$("input[id$=sample_locations]");var data=$.parseJSON(locations.val());var assigned_group=$(e).attr("group");if(!assigned_group||group===assigned_group){$(e).toggleClass("empty").toggleClass("selected");var port=$(e).attr("port");var container=slug($(e).closest("svg").attr("id"));if(!(group in data)){data[group]={}}if(assigned_group===group){$(e).attr("group","");data[group][container]=$.grep(data[group][container],function(value){return value!==port})}else{$(e).attr("group",group);if(!(container in data[group])){data[group][container]=[]}if(port.indexOf(data[group][container])<=0){data[group][container].push(port)}}}locations.val(JSON.stringify(data))}var slug=function(str){let trimmed=$.trim(str);return trimmed.replace(/[^a-z0-9-_]/gi,"-").replace(/-+/g,"-").replace(/^-|-$/g,"")};function setInitial(data){$.each(data,function(e,values){for(var i=0;i<=values.length;i++){if(i>$(".repeat-row").not(".template").length){$(".add").trigger("click")}}});let rows=$(".repeat-row").not(".template");$.each(data,function(e,values){let field=e.split("_set")[0];$.each(values,function(i,val){let input=$(rows[i]).find($(`:input[name="${field}"]`));input.val(val).trigger("change")})});$(".repeat-row.template :input[data-repeat-enable]").removeAttr("readonly").trigger("change")}function openSelector(group){$("span.group-name").html(group);$('#group-select circle.full[group="'+group+'"]').addClass("selected").removeClass("full");$("#group-select circle").off();$("#group-select circle").on("click",function(){selectOne(this,group)})}function initShipmentWizard(){let row_selector=".repeat-row";let rowcount_placeholder="{rowcount}";const registry=new WeakMap;function destroySelect(elem){if(registry.has(elem)){$(elem).removeClass("form-select-multiple").addClass("form-select");registry.get(elem).destroy();registry.delete(elem)}}function setupSelect(elem){if(!registry.has(elem)){$(elem).removeClass("form-select").addClass("form-select-multiple");registry.set(elem,new SlimSelect({select:elem,settings:{maxValuesShown:40}}))}}function update_fields(){$(row_selector+":not(.template)").each(function(pos,row){$(row).find("select[multiple]").each(function(){destroySelect(this)});$(row).find("[id]").each(function(i,item){if(item.id.match(/--\d+$/)){$(item).attr("id",item.id.replace(/--\d+$/,"--"+pos))}else{$(item).attr("id",item.id+"--"+pos)}});$(row).find("label[for]").each(function(i,item){if($(item).attr("for").match(/--\d+$/)){$(item).attr("for",$(item).attr("for").replace(/--\d+$/,"--"+pos))}else{$(item).attr("for",$(item).attr("for")+"--"+pos)}});$(row).find('a[href*="--"]').each(function(i,item){if($(item).attr("href").match(/--\d+$/)){$(item).attr("href",$(item).attr("href").replace(/--\d+$/,"--"+pos))}});$(row).find("select[multiple]").each(function(){setupSelect(this)})})}$(".repeat").each(function(){$(this).find("select[multiple]").each(function(){destroySelect(this)});$(this).on("click",".safe-remove:not(.remove)",function(){let btn=$(this);btn.switchClass("btn-warning","btn-danger",100,"fade",function(){btn.addClass("remove","text-white");if(window.bootstrap&&window.bootstrap.Popover){let pop=bootstrap.Popover.getOrCreateInstance(btn[0],{content:"Click again to confirm",placement:"bottom"});pop.show()}else if(btn.popover){btn.popover({content:"Click again to confirm",placement:"bottom"});btn.popover("show")}});setTimeout(function(){if(window.bootstrap&&window.bootstrap.Popover){let pop=bootstrap.Popover.getInstance(btn[0]);if(pop){pop.dispose()}}else if(btn.popover){btn.popover("dispose")}btn.switchClass("btn-danger","btn-warning",100,"fade",function(){btn.removeClass("remove","text-white")})},3e3)});$(this).repeatable_fields({row_count_placeholder:rowcount_placeholder,row:row_selector,container:".repeat-container",wrapper:".repeat-wrapper",after_add:function(container,row){let row_count=$(container).attr("data-rf-row-count");row_count++;$("*",row).each(function(){$.each(this.attributes,function(){this.value=this.value.replace(rowcount_placeholder,row_count-1)})});$(container).attr("data-rf-row-count",row_count);update_fields()},after_remove:function(container,row){update_fields()}});$(".add").trigger("click");$(".repeat-wrapper").find(".repeat-container").on("sortupdate",function(event,ui){$.each($('input[name$="priority"]'),function(i,e){$(e).val(i)})})})}